import collections
import difflib
import hashlib
import json
from pathlib import Path
import subprocess
import sys

ROOT = Path('/home/drx/MIPStarRE-qpbt/.worktrees/issue-247-standing-owner-policy')
OUT = Path('/home/drx/.cache/mipstarre-dev/sessions')
PREFIX = 'orc-247-20260906-08'
APPROVED = 'ecba3e73c4e572d53967c058db9688829ff8b80f'
PREVIOUS = 'bf8b2d25ad8fcce3a7b683df9f18cbaea4eb8475'
MAIN = '928328ff4d45e5fdc2844b120329a2c241a3a58a'
EVENTS = 'results/telemetry/events.md'

def git(*args):
    return subprocess.check_output(['git', '-C', str(ROOT), *args])

def tree(ref):
    return {p.decode(): m.decode() for r in git('ls-tree', '-rz', ref).split(b'\0')
            if r for m, p in [r.split(b'\t', 1)]}

def blob(ref, path):
    return git('show', f'{ref}:{path}')

def sha(data):
    return hashlib.sha256(data).hexdigest()

def patch(base, head, name, source=False):
    paths = ['--', '.', ':(exclude)results/telemetry'] if source else []
    data = git('diff', '--no-color', base, head, *paths)
    normalized = b''.join(x for x in data.splitlines(keepends=True)
                          if not x.startswith((b'index ', b'@@ ')))
    path = OUT / f'{PREFIX}-{name}.patch'
    path.write_bytes(data)
    return {'path': str(path), 'sha256': sha(data), 'review_hash': sha(normalized),
            'bytes': len(data), 'lines': len(data.splitlines())}

def verify(old, incoming, target):
    base = git('merge-base', old, incoming).decode().strip()
    before, source, after, ancestor = [tree(r) for r in (old, incoming, target, base)]
    failures, authored, incoming_only, raw_rows = [], [], [], []
    for path in sorted(set(before) | set(source) | set(ancestor)):
        if before.get(path) != ancestor.get(path):
            row = {'path': path, 'before': before.get(path), 'after': after.get(path),
                   'identical': before.get(path) == after.get(path)}
            authored.append(row)
            if path != EVENTS and not row['identical']:
                failures.append('Authored bytes changed: ' + path)
        if source.get(path) != ancestor.get(path) and before.get(path) == ancestor.get(path):
            row = {'path': path, 'incoming': source.get(path), 'after': after.get(path),
                   'identical': source.get(path) == after.get(path)}
            incoming_only.append(row)
            if not row['identical']:
                failures.append('Incoming-only bytes changed: ' + path)
        if path.startswith('results/telemetry/') and path.endswith('.jsonl'):
            for parent, entries in ((old, before), (incoming, source)):
                if path not in entries:
                    continue
                if entries.get(path) == after.get(path):
                    raw_rows.append({'path': path, 'parent': parent,
                                     'identical_blob': True, 'missing_occurrences': 0})
                    continue
                original = blob(parent, path).splitlines(keepends=True)
                merged = blob(target, path).splitlines(keepends=True) if path in after else []
                missing = collections.Counter(original) - collections.Counter(merged)
                raw_rows.append({'path': path, 'parent': parent, 'rows': len(original),
                                 'missing_occurrences': sum(missing.values())})
                if missing:
                    failures.append('Raw rows lost: ' + parent + ':' + path)
    merged = blob(target, EVENTS)
    history = []
    for parent in (old, incoming):
        original = blob(parent, EVENTS)
        remaining = iter(merged.splitlines(keepends=True))
        ordered = all(any(line == other for other in remaining)
                      for line in original.splitlines(keepends=True))
        missing = collections.Counter(original.splitlines(keepends=True)) - collections.Counter(
            merged.splitlines(keepends=True))
        history.append({'parent': parent, 'sha256': sha(original),
                        'all_lines_preserved_in_order': ordered,
                        'missing_line_occurrences': sum(missing.values())})
        if missing or (parent == incoming and not ordered):
            failures.append('Event preservation failed: ' + parent)
    blocks = []
    original = blob(old, EVENTS).splitlines(keepends=True)
    for tag, _, _, start, end in difflib.SequenceMatcher(
            None, blob(base, EVENTS).splitlines(keepends=True), original,
            autojunk=False).get_opcodes():
        if tag not in ('insert', 'replace'):
            continue
        content = b''.join(original[start:end])
        blocks.append({'start_line': start + 1, 'end_line': end, 'sha256': sha(content),
                       'preserved_verbatim': content in merged})
        if content not in merged:
            failures.append('Authored event block changed: ' + str(start + 1))
    for path in ('MIPStarRE', 'blueprint', 'references'):
        if git('diff', '--name-only', incoming, target, '--', path):
            failures.append('Mathematics differs from main: ' + path)
    return {'old_head': old, 'incoming': incoming, 'merge_base': base, 'target': target,
            'authored_paths': authored, 'incoming_only_changes': incoming_only,
            'event_history': history, 'authored_event_blocks': blocks,
            'raw_rows': raw_rows, 'failures': failures}

historical = json.loads((OUT / 'orc-247-20260906-07-preservation.json').read_text())
checked = verify(APPROVED, historical['incoming'], PREVIOUS)
for key in ('old_head', 'incoming', 'merge_base', 'target', 'authored_paths',
            'incoming_only_changes', 'event_history', 'authored_event_blocks', 'failures'):
    if historical[key] != checked[key]:
        checked['failures'].append('Historical evidence disagrees: ' + key)
for scope, source in (('complete', False), ('nontelemetry', True)):
    for label, base, head in (('approved', checked['merge_base'], APPROVED),
                              ('refreshed', checked['incoming'], PREVIOUS)):
        result = patch(base, head, 'historical-' + label + '-' + scope, source)
        if any(result[k] != v for k, v in historical['patches'][scope][label].items()):
            checked['failures'].append('Historical patch hash disagrees: ' + label + scope)
report = {'historical_verification': checked}
if len(sys.argv) > 1:
    target = git('rev-parse', sys.argv[1]).decode().strip()
    refreshed = verify(PREVIOUS, MAIN, target)
    approved_events = blob(APPROVED, EVENTS).splitlines(keepends=True)
    final_events = blob(target, EVENTS)
    retained_blocks = []
    for block in checked['authored_event_blocks']:
        content = b''.join(approved_events[block['start_line'] - 1:block['end_line']])
        retained_blocks.append({'sha256': sha(content),
                                'preserved_verbatim': content in final_events})
        if content not in final_events:
            refreshed['failures'].append('Approved event block absent from final: ' + sha(content))
    refreshed['approved_event_blocks_in_final'] = retained_blocks
    approved_base = git('merge-base', MAIN, APPROVED).decode().strip()
    comparisons = {}
    for scope, source in (('full', False), ('source', True)):
        old_patch = patch(approved_base, APPROVED, 'approved-' + scope, source)
        new_patch = patch(MAIN, target, 'final-' + scope, source)
        comparisons[scope] = {'approved': old_patch, 'final': new_patch,
                             'exact_equal': old_patch['sha256'] == new_patch['sha256'],
                             'review_hash_equal': old_patch['review_hash'] == new_patch['review_hash']}
    report.update(final_preservation=refreshed, comparisons=comparisons)
report['failures'] = checked['failures'] + report.get('final_preservation', {}).get('failures', [])
destination = OUT / (PREFIX + ('-preservation.json' if len(sys.argv) > 1 else '-historical.json'))
destination.write_text(json.dumps(report, indent=2) + '\n')
print(json.dumps({'report': str(destination), 'failures': report['failures'],
                  'historical_incoming_paths': len(checked['incoming_only_changes']),
                  'final_incoming_paths': len(report.get('final_preservation', {}).get('incoming_only_changes', [])),
                  'comparisons': report.get('comparisons', {})}, indent=2))
sys.exit(bool(report['failures']))

# patch_hash <base> <head> — sha256 of the diff with the position-dependent
# lines (index, hunk headers) removed: whitespace-SENSITIVE (Lean is
# indentation-sensitive; `git patch-id` would ignore it) but independent of
# where the hunks land after a merge of the base.
patch_hash() {
  git -C "$ROOT" diff --no-color "$1" "$2" | grep -v '^index \|^@@ ' | sha256sum | cut -d' ' -f1
}
